function q(name, dflt) {
  let v="";
  try { v=String(getParam(name,"")||""); } catch(e) { v=""; }
  if(v){ try{v=decodeURIComponent(v);}catch(e2){} return v; }
  try { if(typeof MY_PARAMS!=="undefined" && MY_PARAMS && MY_PARAMS[name]!==undefined && MY_PARAMS[name]!==null) return String(MY_PARAMS[name]); } catch(e3){}
  return dflt||"";
}
function h32(s){
  s=String(s||""); let h=2166136261;
  for(let i=0;i<s.length;i++){h^=s.charCodeAt(i); h=(h*16777619)>>>0;}
  return h.toString(16);
}
function fmtTask(t){
  if(!t) return "";
  if(t.status===2) return "✅ 已完成";
  if(t.status===-1) return "❌ 失败";
  if(t.status===1){
    let pct=t.percent>0?Math.round(t.percent*100)/100+"%":"";
    let rate=t.rateDownload>0?" · "+api.tool.formatSize(t.rateDownload)+"/s":"";
    return "⬇ 下载中 "+pct+rate;
  }
  return "⏳ 等待中";
}
function allTasks(client,maxPages){
  let out=[]; let seen={};
  for(let p=1;p<=maxPages;p++){
    let r=client.listOfflineTask(p); let a=(r&&r.tasks)||[];
    if(!a.length) break;
    let sig=a.length+"|"+(a[0]&&a[0].infoHash||"");
    if(seen[sig]) break; seen[sig]=1;
    for(let i=0;i<a.length;i++) out.push(a[i]);
    if(r.pageCount && p>=r.pageCount) break;
  }
  return out;
}
function findByHash(tasks,hash){
  hash=String(hash||"").toLowerCase();
  for(let i=0;i<tasks.length;i++) if(String(tasks[i].infoHash||"").toLowerCase()===hash) return tasks[i];
  return null;
}
function findByUrl(tasks,url){
  let u=String(url||"").trim();
  for(let i=0;i<tasks.length;i++) if(String(tasks[i].url||"").trim()===u) return tasks[i];
  let m=/[?&]xt=urn:btih:([A-Za-z0-9]+)/i.exec(u);
  if(m && m[1].length===40){
    let hh=m[1].toLowerCase();
    for(let j=0;j<tasks.length;j++) if(String(tasks[j].infoHash||"").toLowerCase()===hh) return tasks[j];
  }
  return null;
}
function validLink(s){ return /^(magnet:\?|ed2k:\/\/|https?:\/\/)/i.test(String(s||"").trim()); }
function getChildren(client,cid){
  let out=[]; let offset=0; let loops=0;
  while(loops<10 && out.length<500){
    let r=client.getFiles(String(cid),{offset:offset,pageSize:50,order:"file_name",asc:"1",showDir:"1"});
    let a=(r&&r.files)||[]; if(!a.length) break;
    for(let i=0;i<a.length && out.length<500;i++) out.push(a[i]);
    offset += 50; loops++;
    if(r.count!==undefined && offset>=r.count) break;
  }
  return out;
}
function findResult(client,t){
  if(t.fileId){
    try { let f=client.getFile(String(t.fileId)); if(f && f.fileId) return f; } catch(e){}
  }
  if(t.dirId){
    try {
      let a=getChildren(client,String(t.dirId));
      for(let i=0;i<a.length;i++) if(t.fileId && String(a[i].fileId)===String(t.fileId)) return a[i];
      for(let j=0;j<a.length;j++) if(t.name && String(a[j].name)===String(t.name)) return a[j];
    } catch(e2){}
  }
  return null;
}
function collectVideos(client,root){
  let videos=[]; let queue=[]; let seen={}; let dirCount=0; let itemCount=0;
  if(!root) return videos;
  if(!root.isDirectory){ if(api.tool.fileKind(root.name)==="video") videos.push(root); return videos; }
  queue.push({id:String(root.fileId),depth:0});
  while(queue.length && dirCount<100 && itemCount<500){
    let cur=queue.shift(); if(seen[cur.id]) continue; seen[cur.id]=1; dirCount++;
    let a=[]; try{a=getChildren(client,cur.id);}catch(e){a=[];}
    for(let i=0;i<a.length && itemCount<500;i++){
      let f=a[i]; itemCount++;
      if(f.isDirectory){ if(cur.depth<3) queue.push({id:String(f.fileId),depth:cur.depth+1}); }
      else if(api.tool.fileKind(f.name)==="video") videos.push(f);
    }
  }
  videos.sort(function(a,b){ return String(a.name||"").localeCompare(String(b.name||""),"zh-CN",{numeric:true}); });
  return videos;
}
function playUrl(f){
  return $().lazyRule(api.player.resolve, JSON.stringify({pc:f.pickCode||"",fid:f.fileId||"",name:f.name||"",kind:"video"}));
}

