hash=String(task.infoHash||hash||"");
d.push({title:(task.status===2?"🎬 ":"📥 ")+String(task.name||"离线任务"),desc:fmtTask(task)+(task.size?" · "+api.tool.formatSize(task.size):"")+"\n"+hash,col_type:"text_1"});

if(task.status===-1){
