if(!root){
  d.push({title:"⚠ 离线已完成，但暂未定位到结果文件",desc:"file_id="+String(task.fileId||"")+" · wp_path_id="+String(task.dirId||"")+"\n可先打开原版所在目录检查，随后刷新本页。",col_type:"text_center_1"});
  if(task.dirId) d.push({title:"📁 打开所在目录",col_type:"text_1",url:"hiker://page/115List?rule=115.简&page=fypage",extra:{cid:String(task.dirId),cname:"离线 - "+String(task.name||"").slice(0,16)}});
  d.push({title:"🔄 重新定位",col_type:"text_1",url:"hiker://page/115Open?rule="+MY_RULE.title+"&page=fypage&hash="+encodeURIComponent(hash)+(src?"&url="+encodeURIComponent(src):"")});
  setResult(d); return;
}
let videos=[];
try { videos=collectVideos(client,root); } catch(e3) { videos=[]; }
if(!videos.length){
  d.push({title:"⚠ 已定位结果，但没有识别到视频文件",desc:String(root.name||"")+"\n可打开目录查看实际内容。",col_type:"text_center_1"});
  let cid=root.isDirectory?root.fileId:(root.parentId||task.dirId);
  if(cid) d.push({title:"📁 打开结果目录",col_type:"text_1",url:"hiker://page/115List?rule=115.简&page=fypage",extra:{cid:String(cid),cname:String(root.name||"离线结果")}});
  setResult(d); return;
}

d.push({title:"✅ 已定位 " + videos.length + " 个视频",desc:root.isDirectory?String(root.name||""):"单文件",col_type:"text_center_1"});
if(videos.length===1){
  let f=videos[0];
  d.push({title:"▶ " + f.name,desc:api.tool.formatSize(f.size),col_type:"movie_1",url:playUrl(f)});
} else {
  d.push({title:"▶ 连续播放全部",desc:"共 "+videos.length+" 个视频",col_type:"text_1",url:$().lazyRule(function(arr){
    let api=$.require('115Api'); let names=[],urls=[],headers=[];
    for(let i=0;i<arr.length;i++){
      try{
        let ret=api.player.resolve(JSON.stringify({pc:arr[i].pc||'',fid:arr[i].fid||'',name:arr[i].name||'',kind:'video'}));
        let obj=JSON.parse(ret); if(obj.urls&&obj.urls[0]){names.push(arr[i].name);urls.push(obj.urls[0]);headers.push((obj.headers&&obj.headers[0])||{});}
      }catch(e){}
    }
    if(!urls.length)return'toast://未能取得可播放直链';
    return JSON.stringify({names:names,urls:urls,headers:headers});
  },videos.map(function(f){return{name:f.name,pc:f.pickCode||'',fid:f.fileId||''};}))});
  for(let i=0;i<videos.length;i++){
    let f=videos[i];
    d.push({title:(i+1)+". "+f.name,desc:api.tool.formatSize(f.size),col_type:"text_1",url:playUrl(f)});
  }
}
